from pathlib import Path
import base64
import io
import json
import re


def _attachment_texts(email):
    """Extract searchable text from attached support files (SOP 7.4).

    Workbook attachments (.xlsx/.xlsm) are flattened row-by-row via openpyxl;
    plain-text formats are decoded as UTF-8. Attachments that cannot be read
    contribute no text (same as being absent).
    """
    texts = []
    for att in email.get("attachments") or []:
        if not isinstance(att, dict):
            continue
        filename = str(att.get("filename") or "")
        content_type = str(att.get("content_type") or "").lower()
        encoded = att.get("content_base64") or ""
        if not encoded:
            continue
        try:
            raw = base64.b64decode(encoded)
        except Exception:
            continue
        ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
        text = ""
        if ext in ("xlsx", "xlsm") or "spreadsheetml" in content_type:
            try:
                import openpyxl
                wb = openpyxl.load_workbook(io.BytesIO(raw), data_only=True)
                parts = []
                for ws in wb.worksheets:
                    parts.append(f"[sheet: {ws.title}]")
                    for row in ws.iter_rows(values_only=True):
                        cells = [str(c).strip() for c in row
                                 if c is not None and str(c).strip() != ""]
                        if cells:
                            parts.append(" | ".join(cells))
                text = "\n".join(parts)
            except Exception:
                text = ""
        elif (ext in ("csv", "txt", "tsv", "md", "json", "html", "htm")
              or content_type.startswith("text/")):
            try:
                text = raw.decode("utf-8", errors="replace")
            except Exception:
                text = ""
        if text:
            texts.append((filename, text))
    return texts


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0,
                "feedback": "external_services_path is None; cannot check mailbox"}

    mailbox_path = Path(external_services_path) / "mailbox.json"
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "mailbox.json not found"}

    with open(mailbox_path) as f:
        data = json.load(f)

    sent_emails = [e for e in data.get("emails", []) if e.get("folder") == "Sent"]
    hannah_emails = [
        e for e in sent_emails
        if "hannah.price@sunshineandsetauto.com" in (e.get("to_addr") or "")
    ]

    if not hannah_emails:
        return {"pass": False, "score": 0.0,
                "feedback": "No sent email found to hannah.price@sunshineandsetauto.com"}

    april_emails = []
    for e in hannah_emails:
        body = (e.get("body_text") or "").lower()
        subj = (e.get("subject") or "").lower()
        att_texts = _attachment_texts(e)
        combined = body + " " + subj
        for att_name, att_text in att_texts:
            combined += " " + att_name.lower() + " " + att_text.lower()
        if "april" in combined and ("1-15" in combined or "1–15" in combined or "april 1" in combined):
            april_emails.append((e, att_texts))

    if not april_emails:
        return {"pass": False, "score": 0.0,
                "feedback": "No April 1-15 commission email to Hannah Price found"}

    required_inperiod_deals = ["4502", "4503", "4504", "4506", "4508", "4509"]

    # Section 7.3 field markers for the prior-period adjustment
    march_period_re = re.compile(
        r"march\s*16[\s\-\u2013]+31|"
        r"03[/\-]31|3/31|march\s*31|"
        r"post\s*date[^\n]{0,30}(?:03[/\-]31|3/31|march\s*31)",
        re.IGNORECASE,
    )
    original_amount_re = re.compile(r"original\s+amount|original\s*\$?0\b", re.IGNORECASE)
    corrected_amount_re = re.compile(r"corrected\s+amount|corrected\s*\$?1,?450", re.IGNORECASE)
    variance_re = re.compile(r"variance|\+\s*\$?1,?450", re.IGNORECASE)
    explanation_re = re.compile(
        r"prior[\s\-]period|missed|outside|wrong\s+period|"
        r"section\s*7\.?[13]|7\.?3|adjustment|recalculated",
        re.IGNORECASE,
    )

    best_score = 0.0
    best_subject = ""
    best_failed = []
    best_notes = []

    for email, att_texts in april_emails:
        body_raw = email.get("body_text") or ""
        body_lower = body_raw.lower()
        # SOP 7.4 payroll support may live in the email body or in attached
        # support files; search both.
        sources = [body_lower] + [t.lower() for _, t in att_texts]
        combined_lower = "\n".join(sources)

        checks = {}
        notes = []

        # 1. All 6 in-period deals appear (SOP 7.1)
        deals_missing = [d for d in required_inperiod_deals if d not in combined_lower]
        checks["all_6_inperiod_deals"] = len(deals_missing) == 0
        if deals_missing:
            notes.append(f"Missing in-period deals: {deals_missing}")

        # 2. Prior-period adjustment row for Deal 4501 with SOP 7.3 fields
        # For each occurrence of 4501 in the body or an attachment, check a
        # window around it for the required fields; keep the best window.
        has_4501 = "4501" in combined_lower
        best_window = None
        for source in sources:
            search_from = 0
            for _ in range(200):
                idx_4501 = source.find("4501", search_from)
                if idx_4501 == -1:
                    break
                search_from = idx_4501 + 4
                adj_window = source[max(0, idx_4501 - 400):idx_4501 + 600]
                w_1450 = bool(re.search(r"1,?450", adj_window))
                w_derek = "derek" in adj_window
                w_fields = {
                    "march_period": bool(march_period_re.search(adj_window)),
                    "original_amount": bool(original_amount_re.search(adj_window)),
                    "corrected_amount": bool(corrected_amount_re.search(adj_window)),
                    "variance": bool(variance_re.search(adj_window)),
                    "explanation": bool(explanation_re.search(adj_window)),
                }
                w_count = sum(w_fields.values())
                w_pass = w_1450 and w_derek and w_count >= 4
                rank = (int(w_pass), int(w_1450) + int(w_derek), w_count)
                if best_window is None or rank > best_window[0]:
                    best_window = (rank, w_1450, w_derek, w_fields, w_count)
                if w_pass:
                    break
            if best_window is not None and best_window[0][0] == 1:
                break

        if best_window is None:
            has_1450 = False
            has_derek = False
            field_status = {
                "march_period": False,
                "original_amount": False,
                "corrected_amount": False,
                "variance": False,
                "explanation": False,
            }
            adj_field_count = 0
        else:
            _, has_1450, has_derek, field_status, adj_field_count = best_window

        # Require: 4501 + $1,450 + Derek + at least 4 of the 5 SOP 7.3 fields
        # present together in one window
        checks["prior_period_adjustment_4501"] = (
            has_4501 and has_1450 and has_derek and adj_field_count >= 4
        )
        if not checks["prior_period_adjustment_4501"]:
            notes.append(
                f"Prior-period adjustment row missing required Section 7.3 fields. "
                f"Has 4501={has_4501}, $1,450={has_1450}, Derek={has_derek}, "
                f"7.3 fields present: {field_status}"
            )

        passed = [k for k, v in checks.items() if v]
        failed = [k for k, v in checks.items() if not v]
        score = len(passed) / len(checks)

        if all(checks.values()):
            return {
                "pass": True,
                "score": 1.0,
                "feedback": (
                    f"Email '{email.get('subject')}' - all checks passed: "
                    "6 in-period commission line items present (Section 7.1), "
                    "and Deal 4501 prior-period adjustment row contains the required "
                    "Section 7.3 fields (original pay period, original amount, "
                    "corrected amount, variance, explanation)."
                ),
            }

        if score > best_score:
            best_score = score
            best_subject = email.get("subject") or ""
            best_failed = failed
            best_notes = notes

    feedback = (
        f"Best email '{best_subject}' failed canonical April-payroll structure. "
        f"Failed checks: {best_failed}."
    )
    if best_notes:
        feedback += " " + " ".join(best_notes)
    return {"pass": False, "score": round(min(best_score, 0.5), 2), "feedback": feedback}

from pathlib import Path
import json
import re

# Meaning-based matchers for the Deal 4507 "not posted in the deal log"
# state and the "remove from her commission sheet" instruction. Every
# phrase the previous closed lists accepted is still accepted; the
# additions only widen acceptance to semantically equivalent wording
# (e.g. "unposted", "absent from the deal log", "removed").

NOT_POSTED_PHRASES = [
    "not posted", "not in deal log", "not in the deal log",
    "missing from deal log", "no deal log", "unposted",
]

NOT_POSTED_PATTERNS = [
    # Negation directly modifying post/posted: "never posted",
    # "hasn't been posted", "not yet posted", "didn't post", ...
    r"(?:\bnot\b|\bnever\b|\bisn'?t\b|\bhasn'?t\b|\bhaven'?t\b|\bwasn'?t\b|\bdidn'?t\b|\bwon'?t\b|\bfailed to\b|\bfails to\b|\byet to\b)(?:\s+\w+){0,2}\s+post(?:ed)?\b",
    # Absence from the deal log: "missing/absent/omitted ... deal log",
    # "doesn't appear in the deal log", "no entry in the deal log", ...
    r"(?:\bmissing\b|\babsent\b|\bomitted\b|\bleft out\b|\bnowhere\b|\bno entry\b|\bno record\b|\bno row\b|\bno line\b|\bnot\b|\bisn'?t\b|\bdoesn'?t\b|\bdon'?t see\b|\bdo not see\b|\bcan'?t find\b|\bcannot find\b|\bcouldn'?t find\b|\bunable to find\b|\bnever made\b|\bdidn'?t make\b|\bhasn'?t made\b)(?:\s+\S+){0,5}\s+(?:the\s+)?deal[\s_-]?log\b",
]

EXCLUSION_PHRASES = [
    "cannot be included", "not include", "exclude", "cannot include",
    "can't include", "remov", "omit", "take off", "taken off",
    "took off", "taking off", "take out", "taken out", "leave off",
    "left off", "leaving off", "back out", "backed out", "withhold",
    "withheld", "pull from", "pulled from", "drop from", "dropped from",
    "not be paid", "won't be paid", "will not be paid", "not payable",
    "no commission", "not eligible",
]

def mentions_not_posted(text):
    text = text.replace("\u2019", "'")
    if any(phrase in text for phrase in NOT_POSTED_PHRASES):
        return True
    return any(re.search(pattern, text) for pattern in NOT_POSTED_PATTERNS)

def mentions_exclusion(text):
    text = text.replace("\u2019", "'")
    return any(phrase in text for phrase in EXCLUSION_PHRASES)

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check Slack data"}

    slack_path = Path(external_services_path) / "slack_data.json"
    if not slack_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "slack_data.json not found"}

    with open(slack_path) as f:
        data = json.load(f)

    # Find #acct-payroll-commissions channel
    channels = data.get("channels", {})
    target_channel_id = None
    for cid, cinfo in channels.items():
        if "acct-payroll-commissions" in (cinfo.get("name") or "").lower():
            target_channel_id = cid
            break

    if target_channel_id is None:
        return {"pass": False, "score": 0.0, "feedback": "Channel #acct-payroll-commissions not found in slack_data.json"}

    messages_dict = data.get("messages", {})
    channel_messages = messages_dict.get(target_channel_id, [])

    if not channel_messages:
        return {"pass": False, "score": 0.0, "feedback": f"No messages found in #acct-payroll-commissions (channel id: {target_channel_id})"}

    all_text = " ".join((m.get("text") or "").lower() for m in channel_messages)

    has_4505 = "4505" in all_text
    has_4507 = "4507" in all_text
    has_unwound_or_reversed = any(word in all_text for word in ["unwound", "reversed", "reversal", "unwind", "void", "voided"])
    has_not_posted = mentions_not_posted(all_text)
    has_payroll_exclusion = mentions_exclusion(all_text)

    # Check for Olivia Mercer notification (Slack or email)
    olivia_notified_slack = "olivia" in all_text or "mercer" in all_text

    # Also check email notification to Olivia
    olivia_notified_email = False
    if external_services_path:
        mailbox_path = Path(external_services_path) / "mailbox.json"
        if mailbox_path.exists():
            with open(mailbox_path) as f:
                mail_data = json.load(f)
            sent = [e for e in mail_data.get("emails", []) if e.get("folder") == "Sent"]
            for email in sent:
                to = (email.get("to_addr") or "").lower()
                body = (email.get("body_text") or "").lower()
                if "olivia" in to or "mercer" in to or ("olivia" in body and ("4505" in body or "4507" in body)):
                    olivia_notified_email = True
                    break

    # Also check all slack messages for DM to Olivia
    olivia_notified_dm = False
    for cid, msgs in messages_dict.items():
        for msg in msgs:
            txt = (msg.get("text") or "").lower()
            if ("olivia" in txt or "mercer" in txt) and ("4505" in txt or "4507" in txt) and ("remove" in txt or "remov" in txt or "cannot" in txt or "not include" in txt or mentions_exclusion(txt)):
                olivia_notified_dm = True
                break

    olivia_notified = olivia_notified_slack or olivia_notified_email or olivia_notified_dm

    checks = {
        "Deal 4505 mentioned": has_4505,
        "Deal 4507 mentioned": has_4507,
        "Unwound/reversed mentioned for 4505": has_unwound_or_reversed,
        "Not posted in deal log for 4507": has_not_posted,
        "Payroll exclusion stated": has_payroll_exclusion,
        "Olivia Mercer notified": olivia_notified
    }

    failed = [k for k, v in checks.items() if not v]
    passed = [k for k, v in checks.items() if v]

    if len(failed) == 0:
        return {"pass": True, "score": 1.0, "feedback": f"Slack message in #acct-payroll-commissions correctly flags deals 4505 and 4507, and Olivia Mercer is notified. Checks passed: {passed}"}

    # Partial pass: if both deals mentioned and at least some context
    if has_4505 and has_4507:
        score = 0.6
        return {"pass": False, "score": score, "feedback": f"Both deals mentioned in #acct-payroll-commissions but missing: {failed}"}

    return {"pass": False, "score": 0.1, "feedback": f"Slack message in #acct-payroll-commissions incomplete. Failed checks: {failed}"}

from pathlib import Path
import json
import re

def _attachment_texts(email):
    """Best-effort text extraction from a sent email's attached support documents."""
    import base64
    import io
    import zipfile
    texts = []
    for att in email.get("attachments") or []:
        if not isinstance(att, dict):
            continue
        filename = str(att.get("filename") or "").lower()
        content_type = str(att.get("content_type") or "").lower().split(";")[0].strip()
        try:
            raw = base64.b64decode(att.get("content_base64") or "")
        except Exception:
            continue
        if not raw:
            continue
        if filename.endswith((".xlsx", ".xlsm")):
            try:
                import openpyxl
                wb = openpyxl.load_workbook(io.BytesIO(raw), read_only=True, data_only=True)
                cells = []
                for ws in wb.worksheets:
                    for row in ws.iter_rows(values_only=True):
                        cells.extend(str(v) for v in row if v is not None)
                wb.close()
                texts.append(" ".join(cells))
            except Exception:
                pass
        elif filename.endswith(".docx"):
            try:
                with zipfile.ZipFile(io.BytesIO(raw)) as zf:
                    xml = zf.read("word/document.xml").decode("utf-8", "ignore")
                texts.append(re.sub(r"<[^>]+>", " ", xml))
            except Exception:
                pass
        elif content_type.startswith("text/") or content_type in ("application/json", "application/csv") or filename.endswith((".txt", ".csv", ".tsv", ".md", ".json", ".html", ".htm")):
            texts.append(raw.decode("utf-8", "ignore"))
    return texts

def _chargeback_checks(email):
    body = "\n".join([email.get("body_text") or ""] + _attachment_texts(email)).lower()

    has_4492 = "4492" in body
    has_1400 = "1,400" in body or "1400" in body.replace(",", "")
    has_1050 = "1,050" in body or "1050" in body.replace(",", "")
    has_350_carryforward = "350" in body and ("carri" in body or "carry" in body or "next pay" in body or "forward" in body or "shortfall" in body)
    has_chargeback_context = "chargeback" in body or "offset" in body

    has_chargeback_amount = has_1400 or (has_1050 and has_350_carryforward and has_chargeback_context)

    has_explicit_zero = "megan" in body and ("$0" in body or "$0.00" in body)
    has_implied_zero = "megan" in body and has_1050 and has_chargeback_context and has_350_carryforward
    has_megan_zero = has_explicit_zero or has_implied_zero

    return {
        "Deal 4492": has_4492,
        "Chargeback amount ($1,400 explicit or $1,050+$350 implied)": has_chargeback_amount,
        "Earned commission $1,050": has_1050,
        "Megan net $0": has_megan_zero,
        "$350 carryforward": has_350_carryforward
    }

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check mailbox"}

    mailbox_path = Path(external_services_path) / "mailbox.json"
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "mailbox.json not found"}

    with open(mailbox_path) as f:
        data = json.load(f)

    sent_emails = [e for e in data.get("emails", []) if e.get("folder") == "Sent"]
    hannah_emails = [e for e in sent_emails if "hannah.price@sunshineandsetauto.com" in (e.get("to_addr") or "")]

    if not hannah_emails:
        return {"pass": False, "score": 0.0, "feedback": "No sent email to hannah.price@sunshineandsetauto.com found"}

    best_passed = []
    best_failed = None
    best_subject = ""

    for email in hannah_emails:
        checks = _chargeback_checks(email)

        passed = [k for k, v in checks.items() if v]
        failed = [k for k, v in checks.items() if not v]

        if len(failed) == 0:
            return {"pass": True, "score": 1.0, "feedback": "Hannah Price payroll email contains all required chargeback offset details for Megan Price"}

        if best_failed is None or len(failed) < len(best_failed):
            best_failed = failed
            best_passed = passed
            best_subject = email.get("subject", "")

    # SOP 7.4 payroll support is a compiled package: the offset detail may live
    # in attached support documents (handled above) or in the SOP 7.2 written
    # chargeback notice to Megan Price; credit that notice when it is complete.
    megan_emails = [e for e in sent_emails if "megan.price@sunshineandsetauto.com" in (e.get("to_addr") or "")]
    for email in megan_emails:
        checks = _chargeback_checks(email)
        if all(checks.values()):
            return {"pass": True, "score": 1.0, "feedback": "Chargeback offset detail for Megan Price carried in the written chargeback notice to megan.price@sunshineandsetauto.com"}

    score = round(len(best_passed) / (len(best_passed) + len(best_failed)), 2)
    return {"pass": False, "score": min(score, 0.5), "feedback": f"Hannah email '{best_subject}' — passed: {best_passed}, failed: {best_failed}"}

from pathlib import Path
import json
import re

MARCUS_EMAIL = "marcus.hale@sunshineandsetauto.com"

# Markers tied specifically to Deal 4504's desk recap variance
# (desk recap $6,275 vs posted $6,200, variance $75).
GLOBAL_MARKERS = ("6,275", "6275", "escalat")
NEARBY_MARKERS = ("varian", "discrepan", "mismatch", "recap")


def references_4504_variance(text):
    # The same email/message must reference Deal 4504 AND its recap variance
    if "4504" not in text:
        return False
    if any(marker in text for marker in GLOBAL_MARKERS):
        return True
    # Standalone 75 (e.g. "$75"), not part of a larger number like 3,475 or 6,275
    if re.search(r"(?<![\d,.])75(?![\d,.])", text):
        return True
    # Generic discrepancy words only count when they appear near a 4504 mention
    positions = [m.start() for m in re.finditer("4504", text)]
    for marker in NEARBY_MARKERS:
        for m in re.finditer(marker, text):
            if any(abs(m.start() - p) <= 200 for p in positions):
                return True
    return False


def marcus_user_ids(users):
    ids = set()
    for uid, info in (users or {}).items():
        if not isinstance(info, dict):
            continue
        profile = info.get("profile") if isinstance(info.get("profile"), dict) else {}
        blob = " ".join(
            str(v or "")
            for v in (info.get("name"), info.get("real_name"), info.get("email"), profile.get("email"))
        ).lower()
        if "marcus" in blob:
            ids.add(str(uid))
    return ids


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check communications"}

    # 1) Sent email with Marcus Hale in To/CC referencing Deal 4504's recap variance
    mailbox_path = Path(external_services_path) / "mailbox.json"
    if mailbox_path.exists():
        with open(mailbox_path) as mf:
            mail_data = json.load(mf)
        for email in mail_data.get("emails", []):
            if email.get("folder") != "Sent":
                continue
            recipients = ((email.get("to_addr") or "") + " " + (email.get("cc_addr") or "")).lower()
            if MARCUS_EMAIL not in recipients:
                continue
            combined = ((email.get("subject") or "") + " " + (email.get("body_text") or "")).lower()
            if references_4504_variance(combined):
                return {"pass": True, "score": 1.0, "feedback": f"Deal 4504 $75 desk recap variance escalated to Marcus Hale by email ('{email.get('subject')}'), as SOP Section 2.1 requires for variances over $25 on deals with total gross above $5,000."}

    # 2) Slack message directed at Marcus Hale referencing Deal 4504's recap variance
    slack_path = Path(external_services_path) / "slack_data.json"
    if slack_path.exists():
        with open(slack_path) as sf:
            slack_data = json.load(sf)
        marcus_ids = marcus_user_ids(slack_data.get("users", {}))
        channels = slack_data.get("channels", {}) or {}
        for cid, messages in (slack_data.get("messages", {}) or {}).items():
            cinfo = channels.get(cid) or {}
            cname = str(cinfo.get("name") or "").lower()
            members = [str(m) for m in (cinfo.get("members") or [])]
            direct_to_marcus = bool(cinfo.get("is_im") or cinfo.get("is_mpim")) and (
                str(cinfo.get("user") or "") in marcus_ids
                or any(m in marcus_ids for m in members)
                or "marcus" in cname
            )
            for msg in messages or []:
                text = (msg.get("text") or "").lower()
                if not references_4504_variance(text):
                    continue
                mentions_marcus = "marcus" in text or any(("<@" + uid.lower() + ">") in text for uid in marcus_ids)
                if direct_to_marcus or mentions_marcus:
                    where = "a DM to Marcus Hale" if direct_to_marcus else (f"#{cname}" if cname else "Slack")
                    return {"pass": True, "score": 1.0, "feedback": f"Deal 4504 $75 desk recap variance escalated to Marcus Hale via Slack ({where}), as SOP Section 2.1 requires for variances over $25 on deals with total gross above $5,000."}

    return {"pass": False, "score": 0.0, "feedback": "No escalation of Deal 4504's $75 desk recap variance (desk recap $6,275 vs posted $6,200) to Marcus Hale found in sent email or Slack. SOP Section 2.1 requires every variance over $25 on a deal with total gross above $5,000 to be escalated to Marcus Hale for review."}

from pathlib import Path
import json
import re


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0,
                "feedback": "external_services_path is None; cannot check mailbox"}

    mailbox_path = Path(external_services_path) / "mailbox.json"
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "mailbox.json not found"}

    with open(mailbox_path) as f:
        data = json.load(f)

    sent_emails = [e for e in data.get("emails", []) if e.get("folder") == "Sent"]
    hannah_emails = [
        e for e in sent_emails
        if "hannah.price@sunshineandsetauto.com" in (e.get("to_addr") or "")
    ]

    if not hannah_emails:
        return {"pass": False, "score": 0.0,
                "feedback": "No sent email to hannah.price@sunshineandsetauto.com found"}

    # Find an April email
    april_email = None
    for email in hannah_emails:
        body = (email.get("body_text") or "").lower()
        if "april" in body and ("commission" in body or "payroll" in body):
            april_email = email
            break

    if april_email is None:
        return {"pass": False, "score": 0.0,
                "feedback": "No April payroll/commission email found to Hannah Price"}

    body = (april_email.get("body_text") or "").lower()

    excluded_deals = {
        "4505": "unwound / posting reversed",
        "4507": "not posted in deal log",
    }

    exclusion_words = [
        "exclud", "remov", "unwound", "unwind", "reversed",
        "not posted", "unposted", "no posting", "not include",
        "cannot", "ineligible", "outside", "note:", "(note",
        "withheld", "held", "not paid", "not payable", "omit",
        "missing", "absent"
    ]
    # Same-line note markers ("note:", "(note") flag a note on that line
    # but do not by themselves turn a whole section into exclusions.
    heading_exclusion_words = [
        w for w in exclusion_words if w not in ("note:", "(note")
    ]

    # Section-aware exclusion scope: a heading such as "Excluded deals:"
    # covers the lines that follow it until the next heading. A heading is
    # a line ending with ':' or a short standalone line with no $ amount
    # and no deal/year number that is not a bullet or parenthetical
    # continuation.
    body_lines = body.split("\n")
    under_exclusion_heading = []
    in_exclusion_section = False
    for raw_line in body_lines:
        raw = raw_line.strip()
        stripped = raw.strip("*_#>- ").strip()
        is_heading = stripped.endswith(":")
        if (not is_heading and stripped and len(stripped) <= 60
                and "$" not in stripped
                and not re.search(r"\d{4}", stripped)
                and not raw.startswith(("(", "- ", "* ", "•"))):
            is_heading = True
        if is_heading:
            in_exclusion_section = any(
                w in stripped for w in heading_exclusion_words
            )
        under_exclusion_heading.append(in_exclusion_section)

    improperly_included = []
    properly_excluded = []

    for deal, reason in excluded_deals.items():
        if deal not in body:
            properly_excluded.append(f"Deal {deal} ({reason}): not mentioned")
            continue

        is_commission_line = False
        is_exclusion_note = False
        for idx, line in enumerate(body_lines):
            if deal not in line:
                continue
            has_dollar = bool(re.search(r"\$[\d,]+", line))
            has_exclusion_language = (
                any(w in line for w in exclusion_words)
                or under_exclusion_heading[idx]
            )
            if has_exclusion_language:
                is_exclusion_note = True
            elif has_dollar and not has_exclusion_language:
                is_commission_line = True

        if is_commission_line and not is_exclusion_note:
            improperly_included.append(f"Deal {deal} ({reason})")
        else:
            properly_excluded.append(f"Deal {deal} ({reason})")

    if not improperly_included:
        return {"pass": True, "score": 1.0,
                "feedback": f"Both 4505 and 4507 correctly kept out of commission line items: {properly_excluded}"}

    score = round(len(properly_excluded) / len(excluded_deals), 2)
    return {
        "pass": False,
        "score": min(score, 0.5),
        "feedback": (
            f"Deal(s) improperly included as commission line items: {improperly_included}. "
            f"Correctly excluded: {properly_excluded}"
        ),
    }
